{
  "name": "monthly_sales_by_category_best_worst",
  "kind": "workflow",
  "description": "Totals monthly sales revenue and units by product category from sales_2026.csv and reports best and worst month overall and per category.",
  "signature": {
    "in": "{\"type\":\"object\",\"properties\":{\"folder\":{\"type\":\"string\"},\"category_filter\":{\"type\":\"string\"},\"from_month\":{\"type\":\"string\"},\"to_month\":{\"type\":\"string\"},\"customer_filter\":{\"type\":\"string\"}},\"required\":[\"folder\"]}",
    "out": "output of s1"
  },
  "steps": [
    {
      "id": "s1",
      "uses": "summarize_monthly_sales_by_category",
      "foreach": null,
      "inputs": [
        {
          "param": "folder",
          "source": "$input.folder"
        },
        {
          "param": "category_filter",
          "source": "$input.category_filter"
        },
        {
          "param": "from_month",
          "source": "$input.from_month"
        },
        {
          "param": "to_month",
          "source": "$input.to_month"
        },
        {
          "param": "customer_filter",
          "source": "$input.customer_filter"
        }
      ]
    }
  ],
  "output_step": "s1",
  "permissions": {
    "net": [],
    "llm": false
  },
  "budget": {
    "max_tokens_per_run": 0
  },
  "lineage": {
    "created_by": "factory",
    "uses": [
      "summarize_monthly_sales_by_category@v1"
    ]
  },
  "example_input": "{\"folder\":\"novak_trading\"}",
  "purpose": "a bot that totals our monthly sales by product category and tells me the best and the worst month\n\nFiles: folder novak_trading",
  "version": 1,
  "build_usd": 0.0925,
  "build_seconds": 42,
  "headline": "Your best month was {best_month.month} with {best_month.revenue_czk} CZK in sales, and your worst was {worst_month.month} with {worst_month.revenue_czk} CZK.",
  "examples": [
    "Which month had the highest sales?",
    "Show me my sales by product category each month",
    "What was my worst performing month?"
  ],
  "voice": "golem",
  "manual_minutes": 45.0,
  "manual_basis": "Aggregating sales data from transaction files by month and category, then identifying peak and trough periods."
}

